    internal partial class PortalBinaryCreateTranslation
    {
        public static readonly PortalBinaryCreateTranslation Instance = new PortalBinaryCreateTranslation();

        public static void FillBinaryStructs(
            IPortal item,
            MutagenFrame frame)
        {
            item.Origin.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
            item.Destination.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
        }

        public static ParseResult FillBinaryRecordTypes(
            IPortal item,
            MutagenFrame frame,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            RecordType nextRecordType,
            int contentLength,
            TypedParseParams translationParams = default)
        {
            nextRecordType = translationParams.ConvertToStandard(nextRecordType);
            switch (nextRecordType.TypeInt)
            {
                case RecordTypeInts.ONAM:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.ONAM = ByteArrayBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Portal_FieldIndex.ONAM;
                }
                case RecordTypeInts.XMBP:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.XMBP = ByteArrayBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Portal_FieldIndex.XMBP;
                }
                case RecordTypeInts.XMRK:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.XMRK = ByteArrayBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Portal_FieldIndex.XMRK;
                }
                case RecordTypeInts.XPPA:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.XPPA = ByteArrayBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Portal_FieldIndex.XPPA;
                }
                default:
                    return ParseResult.Stop;
            }
        }

    }

